{"file_path": "C:\Users\operator\AgentRuns\deployments\case_928ffa76892c\dep_20260803_160854_322d3c49\Workspace\decode_files.py", "content": "#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
还原 Workspace 内“看起来是乱码”的文本文件。

背景：历史项目下的部分 txt/csv 打开后是一堆看不懂的字符。经排查，
它们并不是编码坏了，而是正文被额外做了一层可逆的编码（URL 百分号编码 /
Base64），少数文件其实是正常 UTF-8。

本脚本做的事：
  1. 逐个读取目标目录下的文本文件（只在 Workspace 范围内，不跟随快捷方式）
  2. 自动判定其真实形态：utf-8 / gbk / url-encoded / base64
  3. 解码后校验是否含有足够比例的中文，避免把噪音当成正文
  4. 把还原后的正文写到 _decoded/ 目录，并打印判定结论

用法：
    python decode_files.py
"""

import base64
import binascii
import os
import re
import sys
from urllib.parse import unquote

# 只处理这个根目录，不越界
ROOT = os.path.dirname(os.path.abspath(__file__))
OUT_DIR = os.path.join(ROOT, "_decoded")

# 需要扫描的子目录（相对 ROOT）；None 表示 ROOT 本身
SCAN_DIRS = [None, "在办项目", "历史项目"]

TEXT_EXT = {".txt", ".csv", ".md", ".json", ".log"}

CJK_RE = re.compile(r"[\u4e00-\u9fff]")


def cjk_ratio(s: str) -> float:
    """中文字符占可见字符的比例，用来判断解码是否成功。"""
    visible = [c for c in s if not c.isspace()]
    if not visible:
        return 0.0
    return len(CJK_RE.findall(s)) / len(visible)


def looks_like_text(s: str) -> bool:
    """解码结果是否像正常正文：中文占比够高，且没有大量不可打印字符。"""
    if not s:
        return False
    bad = sum(1 for c in s if ord(c) < 9 or (13 < ord(c) < 32))
    if bad > len(s) * 0.01:
        return False
    return cjk_ratio(s) >= 0.15


def try_plain(raw: bytes):
    """直接按常见中文编码解."""
    for enc in ("utf-8-sig", "utf-8", "gb18030", "gbk"):
        try:
            s = raw.decode(enc)
        except (UnicodeDecodeError, LookupError):
            continue
        if looks_like_text(s):
            return s, enc
    return None, None


def try_urlencoded(raw: bytes):
    """百分号编码，例如 %E4%BA%A4 -> 交"""
    try:
        head = raw.decode("ascii")
    except UnicodeDecodeError:
        return None, None
    if "%" not in head:
        return None, None
    # 百分号序列要占一定比例，避免误判正文里偶然出现的 %
    if len(re.findall(r"%[0-9A-Fa-f]{2}", head)) < 3:
        return None, None
    try:
        s = unquote(head, encoding="utf-8", errors="strict")
    except Exception:
        return None, None
    if looks_like_text(s):
        return s, "url-encoded(utf-8)"
    return None, None


def try_base64(raw: bytes):
    """Base64，可能被换行切断，先去掉空白再解。"""
    try:
        head = raw.decode("ascii")
    except UnicodeDecodeError:
        return None, None
    compact = re.sub(r"\s+", "", head)
    if len(compact) < 8 or not re.fullmatch(r"[A-Za-z0-9+/=_-]+", compact):
        return None, None
    # 兼容 urlsafe 变体
    candidate = compact.replace("-", "+").replace("_", "/")
    candidate += "=" * (-len(candidate) % 4)
    try:
        decoded = base64.b64decode(candidate, validate=False)
    except (binascii.Error, ValueError):
        return None, None
    for enc in ("utf-8", "gb18030"):
        try:
            s = decoded.decode(enc)
        except UnicodeDecodeError:
            continue
        if looks_like_text(s):
            return s, f"base64({enc})"
    return None, None


# 顺序有讲究：先试直解，避免把正常 UTF-8 文本误判成 base64
STRATEGIES = (try_plain, try_urlencoded, try_base64)


def decode_one(path: str):
    with open(path, "rb") as f:
        raw = f.read()
    if not raw.strip():
        return None, "空文件"
    for fn in STRATEGIES:
        text, how = fn(raw)
        if text is not None:
            return text, how
    return None, "无法识别"


def iter_targets():
    for sub in SCAN_DIRS:
        d = ROOT if sub is None else os.path.join(ROOT, sub)
        if not os.path.isdir(d):
            continue
        for name in sorted(os.listdir(d)):
            p = os.path.join(d, name)
            # 明确跳过快捷方式和目录，不跟随到 Workspace 外部
            if os.path.islink(p) or name.lower().endswith(".lnk"):
                print(f"[跳过] {os.path.relpath(p, ROOT)} -> 快捷方式，指向本文件夹之外，按要求不读取")
                continue
            if not os.path.isfile(p):
                continue
            if os.path.splitext(name)[1].lower() not in TEXT_EXT:
                continue
            yield p


def main():
    os.makedirs(OUT_DIR, exist_ok=True)
    ok = fail = 0
    print(f"扫描根目录：{ROOT}\n")
    for path in iter_targets():
        rel = os.path.relpath(path, ROOT)
        text, how = decode_one(path)
        if text is None:
            fail += 1
            print(f"[失败] {rel}  ({how})")
            continue
        ok += 1
        flag = "原样可读" if how.startswith(("utf-8", "gb")) else f"已还原 <- {how}"
        print(f"[成功] {rel}  {flag}")
        out_name = rel.replace(os.sep, "__")
        with open(os.path.join(OUT_DIR, out_name), "w", encoding="utf-8") as f:
            f.write(text)
    print(f"\n完成：成功 {ok} 个，失败 {fail} 个。还原结果在 {OUT_DIR}")
    return 0 if fail == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
"}

